#!/usr/bin/env bash
# R10 content lane draws (pack hosts, swivel bed, pack backgrounds), ONE at a time via studio/bin/art.sh.
# usage: batch_content.sh [name...]  (FORCE=1 to redo). Then: python proc_content.py
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. Palette: sage green walls #689A8D, honey oak wood #BF7948 with darker oak #8E5530, ivory #FFF0D3, rust red #BD582F, warm cream #fff6e5. One warm sunlight from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
K="Place every item on a flat solid pure magenta #ff00ff background with nothing else on it so it can be keyed out; no shadow on the background, items must not touch each other or the image edge."
G="Arrange as a clean grid with wide magenta gaps between items, each item fully visible and the same scale."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }
BG="Portrait 2:3 full-bleed game background, NO magenta. Cozy cat cafe boarding room seen from slightly above, the same layout every time: a wall strip across the top 15 percent with a bay window at the upper right, a wide honey oak table filling the lower 85 percent of the image, small props only in the four corners. The whole centre of the table is EMPTY, plain evenly lit oak planks, ready for a game board. No cats, no characters."
run hosts && g hosts "Square image, a 2x2 sheet of four cute chubby cat characters, each sitting upright facing the viewer, full body, big friendly eyes, in the same felt-toy style. Top-left: a slate blue-grey short-haired cat wearing a navy rain hat (sou'wester) and little green rubber boots, holding a folded paper boat. Top-right: a fluffy cream and white cat wearing a tall white baker's hat, a dab of flour on its nose, holding a golden croissant. Bottom-left: a tortoiseshell calico cat wearing a crown of white daisies, holding a tiny green watering can. Bottom-right: a black cat with big golden eyes wearing a dark blue scarf with small gold stars, holding a little brass telescope. $K $G $S"
run swivel_bed && g swivel_bed "Square image, ONE item centred: a round plush cat bed seen straight from above (top-down), a thick soft rust red #BD582F rim like a donut with a cream #fff6e5 cushion inside, two small brass swivel arrows stitched on the rim pointing clockwise, felt texture. The bed fills about 80 percent of the frame. $K $S"
run bg_rainy && g bg_rainy "$BG Theme: a rainy afternoon. Muted cool light, a sage green wall, the bay window shows grey rain with raindrops running down the glass and soft blue-grey daylight. A yellow umbrella leaning in the bottom-right corner with a small puddle, a pair of green rubber boots bottom-left, a steaming mug top-left on a shelf. Gentle cool blue tint over the warm oak. $S"
run bg_bakery && g bg_bakery "$BG Theme: an early morning bakery kitchen. A warm peach wall with a shelf of bread loaves at the top-left, the bay window glows with golden sunrise, a basket of croissants bottom-right, a flour sack bottom-left with a light dusting of flour on the table edge. Warm golden light. $S"
run bg_garden && g bg_garden "$BG Theme: a garden party on a sunny day. The bay window is wide open onto a bright green garden, a string of small pastel bunting flags across the top, a potted pink tulip pot bottom-left, a little teapot and cupcakes bottom-right, a few flower petals near the corners. Fresh bright spring light. $S"
run bg_starry && g bg_starry "$BG Theme: a calm starry night. A deep blue-green wall, the bay window shows a dark navy sky with a crescent moon and twinkling stars, soft moonlight falling on the oak table, a glowing paper lantern bottom-right, a small brass telescope bottom-left, a candle top-left. Cool calm night colours with a warm lantern glow, still bright enough that the table reads clearly. $S"
echo done $(date +%T)
